-- Prepared only: root may select one bounded read. No business helper invocation.
-- Samples are not whole-population counts; absent samples do not prove absence.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='8s';SET LOCAL lock_timeout='3s';
WITH expected AS MATERIALIZED (SELECT value p FROM jsonb_array_elements('[{"metadata_sha256":"2298d7d2dc6af8f2360df643ed9c05067e625103fe3e09ba59b3fdc1a7ed1f69","oid":"16041469","signature":"astra_ingestion_v1.backfill_plan_snapshot_v2(text,integer)","source_sha256":"67c4b74348ad271d59bc21a901cbfee650ecc91c3a86713b2e29f308094f1ad2"},{"metadata_sha256":"26059708eb74c9b3f291e98da0a74b3b2c381073ec04feb947c07e5fa91a2f8c","oid":"16041471","signature":"astra_ingestion_v1.backfill_seal_plan_v2(text,bigint,text,jsonb)","source_sha256":"6b1b74c618a0f555fd023f7e9980e94c11d1beb556d89815e7e16f6018c5d296"},{"metadata_sha256":"3b039c556a14a96cec82bbe9cf701f6fd45474393b255460fb14d62648087418","oid":"16041466","signature":"astra_ingestion_v1.backfill_snapshot_task_v2(text)","source_sha256":"66cf1ddad758759353ac0e7ca10aa119cbc88b21bee26d1b5f8356df090518b2"}]'::jsonb)),
pin_check AS MATERIALIZED (SELECT count(*)=3 AND bool_and(COALESCE(f.oid::text=e.p->>'oid' AND encode(sha256(convert_to(pg_get_functiondef(f.oid),'UTF8')),'hex')=e.p->>'source_sha256' AND encode(sha256(convert_to((to_jsonb(f)-'prosrc')::text,'UTF8')),'hex')=e.p->>'metadata_sha256',false)) ok FROM expected e LEFT JOIN pg_proc f ON f.oid=to_regprocedure(e.p->>'signature')),
run_scope AS MATERIALIZED (SELECT r.id,r.status,r.fence,r.metadata->>'planner_phase' phase,r.metadata->'planning_complete' planning_complete,r.metadata->>'implementation_owner' owner,r.metadata->>'implementation_lease_until' lease_until,r.metadata->'planner_expected_static_count' expected_static_count,r.metadata->'planner_preexisting_static_count' preexisting_static_count,
 r.status='ACTIVE' AND r.fence=1 AND r.cohort_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND r.cohort_manifest_sha256='4134b415e2c26fcde9fced749c0d54ef51376e23f0d2f8c6ce9ef562f9fab99f' AND r.metadata->>'implementation_owner'='root-replacement-20261030T042603Z' AND isfinite((r.metadata->>'implementation_lease_until')::timestamptz) AND (r.metadata->>'implementation_lease_until')::timestamptz>clock_timestamp() AND r.metadata->>'planner_phase'='SEAL' AND r.metadata->'planning_complete' IS DISTINCT FROM 'true'::jsonb ok
 FROM astra_ingestion_v1.backfill_runs_v2 r WHERE r.id='fixed3000-20250901-20260731-v1-20261030'),
guard AS MATERIALIZED (SELECT p.ok AND r.ok ok FROM pin_check p CROSS JOIN run_scope r),
retained_identity AS MATERIALIZED (SELECT q.id,q.family,q.kind,q.status,q.generation,q.run_fence,q.scope ? 'identity_refresh_of' identity_refresh,q.scope ? 'reuse_parent' reuse_child,(q.kind='alpaca_option_bars' AND q.scope ? 'enumeration_parent') option_child,'retained_identity'::text dynamic_class FROM guard g CROSS JOIN astra_ingestion_v1.backfill_tasks_v2 q WHERE g.ok AND q.run_id='fixed3000-20250901-20260731-v1-20261030' AND q.family='REF01' AND q.kind='retained_identity' ORDER BY q.id LIMIT 9),
retained_archive AS MATERIALIZED (SELECT q.id,q.family,q.kind,q.status,q.generation,q.run_fence,q.scope ? 'identity_refresh_of' identity_refresh,q.scope ? 'reuse_parent' reuse_child,(q.kind='alpaca_option_bars' AND q.scope ? 'enumeration_parent') option_child,'retained_massive_archive'::text dynamic_class FROM guard g CROSS JOIN astra_ingestion_v1.backfill_tasks_v2 q WHERE g.ok AND q.run_id='fixed3000-20250901-20260731-v1-20261030' AND q.family='S02' AND q.kind='retained_massive_archive' ORDER BY q.id LIMIT 9),
identity_refresh AS MATERIALIZED (SELECT q.id,q.family,q.kind,q.status,q.generation,q.run_fence,true identity_refresh,q.scope ? 'reuse_parent' reuse_child,(q.kind='alpaca_option_bars' AND q.scope ? 'enumeration_parent') option_child,'identity_refresh_of'::text dynamic_class FROM guard g CROSS JOIN astra_ingestion_v1.backfill_tasks_v2 q WHERE g.ok AND q.run_id='fixed3000-20250901-20260731-v1-20261030' AND q.scope ? 'identity_refresh_of' ORDER BY q.id LIMIT 9),
candidates AS MATERIALIZED (SELECT * FROM retained_identity UNION ALL SELECT * FROM retained_archive UNION ALL SELECT * FROM identity_refresh),
classified AS MATERIALIZED (SELECT c.*,p.task_id IS NOT NULL has_plan_snapshot,NOT(c.option_child OR c.reuse_child) AND p.task_id IS NULL old_snapshot_query_would_consider,true current_snapshot_task_explicitly_skips,row_number() OVER(PARTITION BY dynamic_class ORDER BY id) sample_number FROM candidates c LEFT JOIN astra_ingestion_v1.backfill_plan_units_v2 p ON p.task_id=c.id),
result AS MATERIALIZED (SELECT jsonb_build_object('schema','astra.planner-seal-dynamic-row-classification/1','observed_at',clock_timestamp(),'source_scope_owner_guard',(SELECT ok FROM guard),'run',(SELECT to_jsonb(r)-'ok' FROM run_scope r),'bounds',jsonb_build_object('statement_timeout','8s','lock_timeout','3s','max_candidates_per_class',9,'max_output_rows_per_class',8,'whole_population_count',false),'classes',(SELECT jsonb_agg(jsonb_build_object('class',dynamic_class,'candidates_seen',n,'candidate_limit_reached',n=9,'old_predicate_missing_snapshot_examples',affected)) FROM (SELECT dynamic_class,count(*) n,count(*) FILTER(WHERE old_snapshot_query_would_consider) affected FROM classified GROUP BY dynamic_class) z),'rows',(SELECT COALESCE(jsonb_agg(to_jsonb(c)-'sample_number' ORDER BY dynamic_class,id),'[]'::jsonb) FROM classified c WHERE sample_number<=8),'application_helpers_invoked',false,'ownership_changed',false,'classification_is_seal_success',false) evidence)
SELECT CASE WHEN octet_length(evidence::text)<=32768 THEN evidence ELSE jsonb_build_object('schema','astra.planner-seal-dynamic-row-classification/1','output_limit_exceeded',true) END evidence FROM result;
COMMIT;
